            }
        },
        "viz_card_05_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#cbd5e1",
                "fontSize": "custom",
                "customFontSize": 12,
                "markdown": "Per\\-logged\\-in\\-user egress leaderboard from Cisco NVM flowdata \\- bytes out, bytes in, flow count, distinct destination hosts, distinct processes\\. Identifies users with abnormally high data movement for IR triage\\."
            }
        },
        "viz_card_05_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_05"
